# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

LUNCH = "gap 12:00-13:00 (60 min)"
QUICK = "gap 09:00-09:45 (45 min)"
OPEN = parse_span("09:00-17:00")


def spans(*texts):
    return [parse_span(text) for text in texts]


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        result = find_gaps(
            spans("09:00-12:00", "13:00-17:00"),
            parse_span("09:00-17:00"),
        )
        self.assertEqual(result, [LUNCH])

    def test_gaps_at_both_ends(self):
        result = find_gaps(
            spans("10:00-11:00"), parse_span("09:00-12:00")
        )
        self.assertEqual(
            result,
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)",
            ],
        )

    def test_overlaps_and_touching_leave_no_gap(self):
        result = find_gaps(
            spans("09:00-12:00", "11:00-14:00",
                  "14:00-17:00"),
            parse_span("09:00-17:00"),
        )
        self.assertEqual(result, [])

    def test_nobody_working(self):
        result = find_gaps([], parse_span("09:00-09:45"))
        self.assertEqual(result, [QUICK])

    def test_unsorted_input(self):
        result = find_gaps(
            spans("13:00-17:00", "09:00-12:00"),
            parse_span("09:00-17:00"),
        )
        self.assertEqual(result, [LUNCH])

    def test_starts_before_opening(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("08:00-12:00"), OPEN)

    def test_ends_after_closing(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("16:00-18:00"), OPEN)


if __name__ == "__main__":
    unittest.main()
